"""Turn a finished graph state into a Markdown report and a JSON summary.

Kept separate from main.py so the formatting can be tested offline.
"""

from __future__ import annotations

import re

from src import config

DISCLAIMER = (
    "*Disclaimer: generated by an AI research system for educational purposes only. "
    "This is not financial advice.*"
)


def estimate_cost(usage_by_model: dict[str, dict]) -> float:
    """Estimate USD cost from LangChain usage metadata ({model: {input_tokens, output_tokens}})."""
    total = 0.0
    for model, usage in usage_by_model.items():
        # Usage may be reported under a longer model name; match on the configured prefix.
        prices = next((p for name, p in config.MODEL_PRICES.items() if model.startswith(name)), None)
        if prices is None:
            continue
        input_price, output_price = prices
        total += usage.get("input_tokens", 0) * input_price / 1e6
        total += usage.get("output_tokens", 0) * output_price / 1e6
    return total


def _nest(markdown: str) -> str:
    """Turn '#' and '##' headings into '###' so agent-written text nests under a report section.

    Agents sometimes start their output with their own title (e.g.
    '## NVDA Technical Assessment'), which would otherwise look like a new
    top-level section of the report.
    """
    return re.sub(r"^#{1,2} ", "### ", markdown, flags=re.MULTILINE)


def _bullets(items: list[str] | None) -> str:
    return "\n".join(f"- {item}" for item in items or []) or "- n/a"


def render_markdown(state: dict, cost_usd: float | None = None) -> str:
    """Render the full research report as Markdown, ending with the disclaimer."""
    ticker, as_of = state["ticker"], state["as_of_date"]
    decision = state.get("decision") or {}
    rating = decision.get("rating", "UNAVAILABLE")
    confidence = decision.get("confidence")

    cost_line = f" · Estimated cost: ${cost_usd:.3f}" if cost_usd is not None else ""
    parts = [
        f"# {ticker} Investment Research Report",
        f"*As of {as_of} · Analysts and debate: `{config.QUICK_MODEL}` · "
        f"Manager: `{config.DEEP_MODEL}`{cost_line}*",
        "",
        "## Decision at a Glance",
        "",
        "| Rating | Confidence | Time horizon |",
        "|---|---|---|",
        f"| **{rating}** | {confidence if confidence is not None else 'n/a'}/100 | "
        f"{decision.get('time_horizon', 'n/a')} |",
        "",
        "**Key reasons**",
        _bullets(decision.get("key_reasons")),
        "",
        "**Key risks**",
        _bullets(decision.get("key_risks")),
        "",
        "---",
        "",
        "## 1. Market / Technical Analysis",
        _nest(state.get("market_report") or "Report unavailable."),
        "",
        "## 2. Fundamentals Analysis",
        _nest(state.get("fundamentals_report") or "Report unavailable."),
        "",
        "## 3. News Analysis",
        _nest(state.get("news_report") or "Report unavailable."),
        "",
        "## 4. Sentiment Analysis",
        _nest(state.get("sentiment_report") or "Report unavailable."),
        "",
        "## 5. Bull vs. Bear Debate",
        _nest(state.get("debate_history") or "No debate took place."),
        "",
        "## 6. Research Manager Decision",
        _nest(state.get("investment_plan") or "Unavailable."),
        "",
        "---",
        "",
        DISCLAIMER,
    ]
    return "\n".join(parts) + "\n"


def build_json_summary(state: dict, usage_by_model: dict, cost_usd: float, report_path: str) -> dict:
    """The machine-readable result of one run."""
    return {
        "ticker": state["ticker"],
        "as_of_date": state["as_of_date"],
        "decision": state.get("decision"),
        "models": {"quick": config.QUICK_MODEL, "deep": config.DEEP_MODEL},
        "debate_rounds": state.get("debate_count", 0) // 2,
        "usage": {
            model: {"input_tokens": u.get("input_tokens", 0), "output_tokens": u.get("output_tokens", 0)}
            for model, u in usage_by_model.items()
        },
        "estimated_cost_usd": round(cost_usd, 4),
        "report_path": report_path,
        "disclaimer": "Educational project. Not financial advice.",
    }
